```javascript
// Function to check if user has consented to a specific data category
function hasConsented(category) {
    const userPreferences = getUserPreferences();
    return userPreferences[category] === 'granted';
}

// Function to set user consent for a specific category
function setConsent(category, consentStatus) {
    const userPreferences = getUserPreferences();
    userPreferences[category] = consentStatus;
    saveUserPreferences(userPreferences);
}

// Function to get user's consent preferences from local storage
function getUserPreferences() {
    const storedPreferences = localStorage.getItem('userPreferences');
    return storedPreferences ? JSON.parse(storedPreferences) : {};
}

// Function to save user's consent preferences to local storage
function saveUserPreferences(preferences) {
    localStorage.setItem('userPreferences', JSON.stringify(preferences));
}

// Example usage:

// Check if user has consented to marketing emails
if (hasConsented('marketing')) {
    console.log('User has granted consent for marketing emails.');
    // Enable marketing-related features or display content
